package ru.neverland.archaeology.restoration;
import java.util.*;import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.*;import org.bukkit.inventory.*;import org.bukkit.plugin.java.JavaPlugin;
import ru.neverland.archaeology.util.ColorUtil;import ru.neverland.core.*;import static ru.neverland.archaeology.restoration.RestorationBook.*;

/** Exact viewer/window checks run again on the player's entity scheduler. */
public final class RestorationMenu implements Listener {
    private final JavaPlugin plugin;private final RestorationService service;
    private static final class View implements InventoryHolder{final UUID viewer;final boolean admin;final Map<Integer,Runnable> actions=new HashMap<>();Inventory inventory;View(UUID player,boolean admin){viewer=player;this.admin=admin;}public Inventory getInventory(){return inventory;}}
    public RestorationMenu(JavaPlugin plugin,RestorationService service){this.plugin=plugin;this.service=service;}
    private boolean allowed(Player p,boolean admin){return p.isOnline()&&(admin?(p.isOp()||p.hasPermission("townyarchaeology.admin")):p.hasPermission("townyarchaeology.use"));}
    private View view(Player p,String title,boolean admin){if(!allowed(p,admin))throw new IllegalStateException("Нет доступа к этому разделу.");var v=new View(p.getUniqueId(),admin);v.inventory=MenuStyle.inventory(plugin,v,54,title);return v;}
    private void navigation(View v,Player p,String screen,int page,int total){button(v,45,Material.BRICK,"Мои фрагменты",List.of("Получить подтверждённые находки"),()->open(p,"fragments",0));button(v,47,Material.ANVIL,"Реставрация",List.of("Собрать целый артефакт из разных частей"),()->open(p,"restore",0));button(v,49,Material.ARROW,"Главное меню",List.of(),()->p.performCommand("archaeology"));button(v,51,Material.RECOVERY_COMPASS,"Целевой поиск",List.of("Известные раскопки для нужного артефакта"),()->open(p,"search",0));button(v,53,Material.WRITABLE_BOOK,"Мои передачи",List.of("История и проверка сохранения"),()->history(p,0,false));if(page>0)button(v,46,Material.ARROW,"Предыдущая страница",List.of(),()->open(p,screen,page-1));if((page+1)*45<total)button(v,52,Material.ARROW,"Следующая страница",List.of(),()->open(p,screen,page+1));}
    public void open(Player player,String screen,int requested){try(var guard=SuiteState.guard()){
        if(screen.equals("history")){history(player,requested,false);return;}var v=view(player,switch(screen){case "restore"->"Реставрация артефактов";case "search"->"Поиск нужного артефакта";default->"Фрагменты с раскопок";},false);
        if(!screen.equals("search")&&!service.ready()){button(v,22,Material.BARRIER,"Временно недоступно",List.of(service.availability(),"Предметы и начатые операции сохранены."),null);navigation(v,player,screen,0,0);player.openInventory(v.inventory);return;}
        if(screen.equals("fragments")){var rows=service.repository().state().fragments().values().stream().filter(f->f.finder().equals(player.getUniqueId())&&f.phase()==FragmentPhase.MAILBOX).sorted(Comparator.comparingLong(Fragment::at).reversed().thenComparing(Fragment::id)).toList();int page=page(requested,rows.size());for(int i=page*45;i<Math.min(rows.size(),(page+1)*45);i++){var f=rows.get(i);button(v,i%45,Material.BRICK,name(f.recipe().artifact()),List.of("Часть "+f.part()+" из "+f.recipe().parts(),"Редкость: "+rarity(f.recipe().rarity()),"Найдено: "+date(f.at()),"Нажмите, чтобы получить в инвентарь.","При полном инвентаре находка останется здесь."),()->{service.transfer().claim(player,f.id());player.sendMessage("§eНаходка сохраняется; дождитесь результата.");});}if(rows.isEmpty())button(v,22,Material.BRUSH,"Пока нет новых фрагментов",List.of("Ищите их при расчистке известных раскопок.","Фрагмент — дополнительная находка с вероятностью.","Части в инвентаре смотрите в «Реставрации»."),null);navigation(v,player,screen,page,rows.size());}
        else{var rows=service.registry().artifacts().stream().sorted(Comparator.comparing(d->d.id())).toList();int page=page(requested,rows.size());for(int i=page*45;i<Math.min(rows.size(),(page+1)*45);i++){var d=rows.get(i);if(screen.equals("search"))button(v,i%45,d.material(),name(d.id()),List.of("Показать известные участки, где может", "встречаться этот артефакт.","Наличие конкретной добычи не гарантировано."),()->search(player,d.id()));else{var groups=service.transfer().groups(player,d.id());var lore=new ArrayList<String>();if(groups.isEmpty())lore.add("В инвентаре нет подходящих частей.");for(var group:groups.stream().limit(4).toList())lore.add("Разных частей: "+group.stream().map(Fragment::part).distinct().count()+" / "+group.get(0).recipe().parts()+" • "+rarity(group.get(0).recipe().rarity()));lore.add("Нужны все разные части одного рецепта.");lore.add("Перед сборкой появится подтверждение.");button(v,i%45,d.material(),name(d.id()),lore,()->confirm(player,d.id()));}}navigation(v,player,screen,page,rows.size());}
        player.openInventory(v.inventory);
    }}
    public void confirm(Player player,String artifact){try(var guard=SuiteState.guard()){service.requireReady();var parts=service.transfer().restorable(player,artifact);if(parts.isEmpty())throw new IllegalStateException("Не хватает разных частей. Проверьте их номера в меню реставрации.");var ids=parts.stream().map(Fragment::id).toList();var v=view(player,"Подтвердить реставрацию",false);button(v,13,Material.ANVIL,name(artifact),List.of("Будут использованы разные части: "+parts.size(),"Вы получите один целый артефакт.","Его можно передать в обычный городской музей.","Деньги за реставрацию не списываются."),null);button(v,29,Material.LIME_DYE,"Собрать артефакт",List.of("Использовать указанные части один раз"),()->{service.transfer().restore(player,artifact,ids);player.sendMessage("§eРеставрация сохраняется. Повторно нажимать не нужно.");});button(v,33,Material.ARROW,"Вернуться без изменений",List.of(),()->open(player,"restore",0));player.openInventory(v.inventory);}}
    public void search(Player player,String artifact){try(var guard=SuiteState.guard()){var hints=service.search(player,artifact);var v=view(player,"Где искать: "+name(artifact),false);int slot=0;for(var hint:hints)button(v,slot++,Material.RECOVERY_COMPASS,ColorUtil.color(hint.siteName()),List.of("Может содержать: "+name(artifact),"Расстояние: около "+Math.round(Math.sqrt(hint.distanceSquared()))+" блоков","Координаты: "+hint.x()+", "+hint.y()+", "+hint.z(),"Участок известен с "+date(hint.knownAt()),"Добыча могла измениться; это ориентир."),null);if(hints.isEmpty())button(v,22,Material.COMPASS,"Подходящих участков рядом нет",List.of("Показаны только известные незавершённые раскопки", "в вашем мире и в пределах радиуса поиска.","Новые места не создаются по запросу."),null);button(v,45,Material.ARROW,"Выбрать другой артефакт",List.of(),()->open(player,"search",0));player.openInventory(v.inventory);}}
    public void history(Player player,int requested,boolean admin){try(var guard=SuiteState.guard()){var v=view(player,admin?"Сверка реставрации":"Мои передачи артефактов",admin);var rows=service.repository().state().operations().values().stream().filter(op->admin||op.player().equals(player.getUniqueId())).sorted(Comparator.comparing((Operation o)->!o.pending()).thenComparing(Comparator.comparingLong(Operation::at).reversed())).toList();int page=page(requested,rows.size());for(int i=page*45;i<Math.min(rows.size(),(page+1)*45);i++){var op=rows.get(i);button(v,i%45,op.pending()?Material.REDSTONE_BLOCK:Material.PAPER,(op.kind()==Kind.CLAIM?"Получение: ":"Реставрация: ")+name(op.recipe().artifact()),List.of("Статус: "+phase(op.phase()),"Игрок: "+op.playerName(),"Начало: "+date(op.at()),"ID: "+op.id(),"Нажмите для подробностей."),()->details(player,op.id(),admin));}if(rows.isEmpty())button(v,22,Material.PAPER,"Передач пока нет",List.of(),null);button(v,45,Material.ARROW,"Назад",List.of(),()->open(player,"fragments",0));if(page>0)button(v,46,Material.ARROW,"Предыдущая страница",List.of(),()->history(player,page-1,admin));if((page+1)*45<rows.size())button(v,52,Material.ARROW,"Следующая страница",List.of(),()->history(player,page+1,admin));button(v,49,Material.SPYGLASS,"Обновить",List.of(),()->history(player,page,admin));player.openInventory(v.inventory);}}
    private void details(Player player,UUID id,boolean admin){var op=service.repository().state().operations().get(id);if(op==null||!admin&&!op.player().equals(player.getUniqueId()))throw new IllegalArgumentException("Операция недоступна.");var v=view(player,"Проверка одной передачи",admin);var lore=new ArrayList<String>(List.of("Статус: "+phase(op.phase()),"Игрок: "+op.playerName(),"ID: "+op.id(),"Результат: "+op.output(),op.note()));for(UUID input:op.fragments())lore.add("Часть: "+input);button(v,13,Material.WRITABLE_BOOK,name(op.recipe().artifact()),lore,null);if(op.phase()==Phase.ARMED||op.phase()==Phase.REVIEW)button(v,31,Material.SPYGLASS,"Проверить сохранение игрока",List.of("Получатель должен находиться на сервере.","Проверится квитанция сохранённого инвентаря.","Предметы повторно не выдаются и не изымаются.","Без подтверждения операция останется на проверке."),()->reconcile(player,op,admin,v));button(v,45,Material.ARROW,"Назад",List.of(),()->history(player,0,admin));player.openInventory(v.inventory);}
    private void reconcile(Player viewer,Operation op,boolean admin,View menu){if(!allowed(viewer,admin))throw new IllegalStateException("Доступ отозван.");var target=Bukkit.getPlayer(op.player());if(target==null)throw new IllegalStateException("Получатель должен зайти на сервер для проверки.");SuiteScheduler.entity(plugin,target,()->{if(!allowed(viewer,admin)||!admin&&!viewer.getUniqueId().equals(op.player()))return;service.transfer().reconcile(target,op.id()).whenComplete((ok,error)->SuiteScheduler.entity(plugin,viewer,()->{if(!allowed(viewer,admin))return;viewer.sendMessage(error!=null?"§eПроверка не завершена; предметы не выдавались.":Boolean.TRUE.equals(ok)?"§aСохранение подтверждено. Повторной выдачи не было.":"§eНет точного подтверждения. Операция остаётся на проверке.");if(viewer.getOpenInventory().getTopInventory()==menu.inventory)details(viewer,op.id(),admin);}));});viewer.sendMessage("§eПроверяем сохранение; инвентарь не изменяется.");}
    @EventHandler public void click(InventoryClickEvent event){if(!(event.getView().getTopInventory().getHolder() instanceof View view))return;event.setCancelled(true);if(!(event.getWhoClicked() instanceof Player player)||!view.viewer.equals(player.getUniqueId())||event.getClick()!=ClickType.LEFT||event.getRawSlot()<0||event.getRawSlot()>=54)return;var action=view.actions.get(event.getRawSlot());if(action==null)return;SuiteScheduler.entity(plugin,player,()->{if(!allowed(player,view.admin)||SuiteState.frozen(plugin.getName())||player.getOpenInventory().getTopInventory()!=view.inventory)return;try{action.run();}catch(RuntimeException error){player.sendMessage("§e"+error.getMessage());}});}
    @EventHandler public void drag(InventoryDragEvent event){if(event.getView().getTopInventory().getHolder() instanceof View)event.setCancelled(true);}
    private void button(View view,int slot,Material material,String title,List<String> lore,Runnable action){var item=new ItemStack(material);var meta=item.getItemMeta();meta.setDisplayName(MenuStyle.nameLegacy(ColorUtil.color("&f"+title)));meta.setLore(MenuStyle.loreStrings(lore.stream().map(ColorUtil::color).toList()));meta.addItemFlags(ItemFlag.HIDE_ATTRIBUTES);item.setItemMeta(meta);view.inventory.setItem(slot,item);if(action!=null)view.actions.put(slot,action);}
    private String name(String artifact){var d=service.registry().artifact(artifact);return ColorUtil.color(d==null?artifact:d.name());}private String rarity(String rarity){return ColorUtil.color(service.registry().rarity(rarity).name());}
    private static int page(int requested,int total){return Math.max(0,Math.min(requested,Math.max(0,(total-1)/45)));}private static String date(long at){return java.time.format.DateTimeFormatter.ofPattern("dd.MM HH:mm").withZone(java.time.ZoneId.of("Europe/Moscow")).format(java.time.Instant.ofEpochMilli(at))+" МСК";}
    private static String phase(Phase phase){return switch(phase){case PREPARED->"Подготовка; предметы ещё не менялись";case ARMED,REVIEW->"Нужна проверка сохранения";case COMPLETE->"Подтверждено";case CANCELLED->"Без передачи предметов";};}
}
